                </Button>
                <Popconfirm title="确认删除该平台？" onConfirm={() => deleteMutation.mutate(record.id)}>
                  <Button type="link" danger>
                    删除
                  </Button>
                </Popconfirm>
              </Space>
            )
          }
        ]}
        dataSource={data}
        loading={isLoading}
      />
      <BaseModal
        open={open}
        title={editing ? '编辑平台' : '新增平台'}
