          form={form}
          layout="vertical"
          onFinish={(values) => (editing ? updateMutation.mutate({ id: editing.id, payload: values }) : createMutation.mutate(values))}
        >
          <Form.Item label="平台名称" name="name" rules={[{ required: true }]}>
            <Input />
