      }
    >
      <Tree defaultExpandAll treeData={buildDepartmentTree(departments, setEditing, deleteMutation.mutate)} />
      <BaseModal
        open={open}
        title={editing ? '编辑部门' : '新增部门'}
        onCancel={() => {
          setOpen(false);
          setEditing(null);
          form.resetFields();
