              style={{ width: 240 }}
              onSearch={(value) => setKeyword(value.trim())}
              onChange={(event) => {
                if (!event.target.value) {
                  setKeyword('');
                }
              }}
            />
            {activeTab !== 'records' ? (
              <Button
                type="primary"
                disabled={rowActionPending}
                onClick={() => {
                  setEditing(null);
                  form.resetFields();
                  submissionKeyRef.current = undefined;
                  setOpen(true);
                }}
              >
                新增
              </Button>
            ) : null}
          </Space>
        }
      >
        <Tabs
          activeKey={activeTab}
